import React, { useRef, useState } from 'react';
import api from '../services/api';

// Botón que permite tomar una foto (en celulares abre la cámara directo gracias a
// "capture") o elegir una imagen del dispositivo. Sube el archivo al backend y
// devuelve la URL pública ya lista para guardar en el producto/categoría.
const ImageUploadButton = ({ value, onChange, label = 'Imagen' }) => {
  const fileInputRef = useRef(null);
  const [uploading, setUploading] = useState(false);
  const [error, setError] = useState('');

  const handleFile = async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setUploading(true);
    setError('');
    try {
      const formData = new FormData();
      formData.append('image', file);
      const res = await api.post('/uploads/image', formData, {
        headers: { 'Content-Type': 'multipart/form-data' },
      });
      onChange(res.data.data.url);
    } catch (err) {
      setError(err.response?.data?.message || 'Error al subir la imagen');
    } finally {
      setUploading(false);
      e.target.value = '';
    }
  };

  return (
    <div>
      <label style={{ color: '#94a3b8', fontSize: 12, display: 'block', marginBottom: 6 }}>{label}</label>
      <div style={{ display: 'flex', gap: 10, alignItems: 'center' }}>
        <div style={{
          width: 64, height: 64, borderRadius: 10, flexShrink: 0,
          background: value ? `url(${value}) center/cover` : '#334155',
          display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 24,
          border: '1px solid #475569',
        }}>
          {!value && '🖼️'}
        </div>
        <div style={{ flex: 1 }}>
          <input
            type="text"
            className="input"
            placeholder="URL de imagen (o sube/toma una foto)"
            value={value || ''}
            onChange={e => onChange(e.target.value)}
            style={{ marginBottom: 6 }}
          />
          <div style={{ display: 'flex', gap: 8 }}>
            <button
              type="button"
              onClick={() => fileInputRef.current?.click()}
              disabled={uploading}
              className="btn"
              style={{ background: '#334155', color: '#e2e8f0', padding: '6px 12px', fontSize: 12 }}
            >
              {uploading ? 'Subiendo...' : '📷 Tomar foto / Subir imagen'}
            </button>
            {value && (
              <button
                type="button"
                onClick={() => onChange('')}
                className="btn"
                style={{ background: 'rgba(239,68,68,0.1)', color: '#ef4444', padding: '6px 12px', fontSize: 12 }}
              >
                Quitar
              </button>
            )}
          </div>
          {/* "capture" hace que en celulares se abra directo la cámara; en desktop simplemente abre el explorador de archivos */}
          <input
            ref={fileInputRef}
            type="file"
            accept="image/*"
            capture="environment"
            onChange={handleFile}
            style={{ display: 'none' }}
          />
          {error && <p style={{ color: '#ef4444', fontSize: 11, marginTop: 4 }}>{error}</p>}
        </div>
      </div>
    </div>
  );
};

export default ImageUploadButton;
